# MIR4-CANONICAL-EXECUTABLE-TEST
param([string]$RepoRoot='', [switch]$RequireLocalEvidence, [switch]$AllowActive)
$ErrorActionPreference='Stop'
if(-not$RepoRoot){$RepoRoot=(Resolve-Path(Join-Path $PSScriptRoot '../..')).Path}
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path
. (Join-Path $RepoRoot 'tools/lib/mir4/BootstrapMaterialization.ps1')
. (Join-Path $RepoRoot 'tools/lib/validation/PackageIdentity.ps1')
. (Join-Path $RepoRoot 'tools/mir/application/assurance/EnvironmentEvidence.ps1')
function Assert-A03Closure{param([bool]$Condition,[string]$Code)if(-not$Condition){throw $Code}}
function Get-A03ClosureSha256{param([string]$Path)(Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToUpperInvariant()}
function Resolve-A03ClosurePath{param([string]$RelativePath,[bool]$Required=$false)
  Assert-A03Closure($RelativePath-cmatch'^[A-Za-z0-9._/-]+$'-and$RelativePath-notmatch'(^|/)\.\.(/|$)')"[mir4-a03-closure-relative-path] $RelativePath"
  $path=[IO.Path]::GetFullPath((Join-Path $RepoRoot $RelativePath));$prefix=$RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
  Assert-A03Closure($path.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase))"[mir4-a03-closure-path-escape] $RelativePath"
  if($Required){Assert-A03Closure(Test-Path -LiteralPath $path -PathType Leaf)"[mir4-a03-closure-evidence-missing] $RelativePath"};$path
}
function Get-A03ClosureRecord{param([string]$RelativePath,[string]$SchemaPath)
  $path=Resolve-A03ClosurePath $RelativePath $true;$raw=Get-Content -Raw -LiteralPath $path
  Assert-A03Closure($raw|Test-Json -SchemaFile(Join-Path $RepoRoot $SchemaPath))"[mir4-a03-closure-schema] $RelativePath"
  Assert-A03Closure($raw-notmatch'(?i)(?:[A-Z]:[\/]|\\\\)')"[mir4-a03-closure-private-path] $RelativePath"
  $record=$raw|ConvertFrom-Json -Depth 100 -DateKind String;Assert-A03Closure(Test-MIR4BootstrapRecordHash $record)"[mir4-a03-closure-self-hash] $RelativePath";$record
}
