    if(@($Proof.invariants.PSObject.Properties|Where-Object{$_.Name-match'authorized$'-and[bool]$_.Value}).Count-ne0){return $false}
    if([string]$Dossier.authority_observation.record_sha256-cne[string]$A00.record_sha256-or(ConvertTo-MIR4BootstrapCanonicalJson $Dossier.environment_lock)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.environment_lock)-or[string]$Dossier.environment_lock.digest-cne[string]$Lock.digest-or[string]$Dossier.execution_proof.record_sha256-cne[string]$Proof.record_sha256){return $false}
    if((ConvertTo-MIR4BootstrapCanonicalJson $Dossier.runtime_result.file)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.execution.runtime.result_file)-or[string]$Dossier.runtime_result.record_sha256-cne[string]$Proof.execution.runtime.record_sha256-or(ConvertTo-MIR4BootstrapCanonicalJson $Dossier.runtime_result.factorio_log)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.execution.runtime.factorio_log)-or(ConvertTo-MIR4BootstrapCanonicalJson $Dossier.runtime_result.save)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.execution.runtime.save)-or[string]$Dossier.observation.canonical_sha256-cne[string]$Proof.observation.canonical_sha256-or(ConvertTo-MIR4BootstrapCanonicalJson $Dossier.observation.value)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.observation.value)){return $false}
    if([string]$Dossier.initial_observation_artifacts.observer_archive_sha256-cne'D8547266E67E5C9E3CA1B1CDCAF1830EF3DEB9A4E706776189663FE0F9478F8B'-or[string]$Dossier.initial_observation_artifacts.observer_source_sha256.data_final_fixes-cne'A67CCA976BFA5F6DD02447954C3D1587E8D19814BDEF64734216801A2EDB9E71'-or[string]$Dossier.initial_observation_artifacts.observer_source_sha256.info-cne'74C59AB562F9249D9800EDACF71A71F5D62E04BB7BFE8E1B4B6DB532F0E8E4ED'-or[string]$Dossier.governed_run_observer.archive_sha256-cne[string]$Proof.configuration.governed_observer.archive_sha256-or(ConvertTo-MIR4BootstrapCanonicalJson $Dossier.governed_run_observer.source_sha256)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.configuration.governed_observer.source_sha256)){return $false}
    if([string]$Receipt.authority_observation.record_sha256-cne[string]$A00.record_sha256-or[string]$Receipt.dossier.record_sha256-cne[string]$Dossier.record_sha256-or(ConvertTo-MIR4BootstrapCanonicalJson $Receipt.environment_lock)-cne(ConvertTo-MIR4BootstrapCanonicalJson $Proof.environment_lock)-or[string]$Receipt.environment_lock.digest-cne[string]$Lock.digest-or[string]$Receipt.execution_proof.record_sha256-cne[string]$Proof.record_sha256){return $false}
