function Assert-A03Artifact{param($Artifact)
  $path=Resolve-A03ClosurePath([string]$Artifact.path)$true;Assert-A03Closure((Get-A03ClosureSha256 $path)-ceq[string]$Artifact.sha256-and[long](Get-Item -LiteralPath $path).Length-eq[long]$Artifact.bytes)"[mir4-a03-closure-artifact] $($Artifact.path)"
}
$root='spec/programmes/evidence/synthesis-2026-09-10';$a00Relative="$root/a00-current-authority-observation.json";$lockRelative="$root/a03-k2-k2so-f210-current.lock.json";$proofRelative="$root/a03-k2-k2so-f210-execution-proof.json";$dossierRelative="$root/a03-k2-k2so-f210-intake-dossier.json";$receiptRelative="$root/a03-k2-k2so-f210-intake-receipt.json"
$a00=Get-A03ClosureRecord $a00Relative 'spec/schemas/mir4-a00-current-authority-observation-v1.schema.json'
$lockPath=Resolve-A03ClosurePath $lockRelative $true;$lockRaw=Get-Content -Raw -LiteralPath $lockPath;Assert-A03Closure($lockRaw|Test-Json -SchemaFile(Join-Path $RepoRoot 'spec/schemas/preview/mir4-environment-lock-v1.schema.json'))'[mir4-a03-closure-lock-schema]';$lock=$lockRaw|ConvertFrom-Json -Depth 100 -DateKind String;Assert-A03Closure(Test-MIR4EnvironmentLockV1 $lock)'[mir4-a03-closure-lock]'
