$proof=Get-A03ClosureRecord $proofRelative 'spec/schemas/mir4-a03-k2-k2so-execution-proof-v1.schema.json';$dossier=Get-A03ClosureRecord $dossierRelative 'spec/schemas/mir4-a03-k2-k2so-intake-dossier-v1.schema.json';$receipt=Get-A03ClosureRecord $receiptRelative 'spec/schemas/mir4-a03-k2-k2so-intake-receipt-v1.schema.json'
Assert-A03Closure(Test-A03CoreBindings $a00 $lock $proof $dossier $receipt)'[mir4-a03-closure-cross-bindings]'
$expectedObservation=Get-Content -Raw -LiteralPath(Join-Path $RepoRoot 'fixtures/assert-k2-k2so-f210-intake/expected-observation.json')|ConvertFrom-Json -Depth 100 -DateKind String;Assert-A03Closure((ConvertTo-MIR4BootstrapCanonicalJson $proof.observation.value)-ceq(ConvertTo-MIR4BootstrapCanonicalJson $expectedObservation))'[mir4-a03-closure-exact-observation]'
Assert-A03Closure((@($dossier.explicit_non_claims)-join'|')-ceq'A04 science-phase behavior|progression qualification|upgrade or reload qualification|public compatibility support|release qualification')'[mir4-a03-closure-nonclaims]'
Assert-A03Closure([string]$dossier.historical_lineage.status-ceq'preserved-separate-not-current-proof'-and[string]$dossier.historical_lineage.old_admitted_campaign.status-ceq'preserved-old-admitted-campaign-not-current-proof'-and[string]$dossier.historical_lineage.pre_engine_failure.status-ceq'preserved-pre-engine-failure-not-gameplay-proof'-and[string]$dossier.historical_lineage.superseded_pass.status-ceq'superseded-by-final-runner-fingerprint-not-current-proof'-and[string]$dossier.historical_lineage.prior_admitted_run.status-ceq'superseded-by-current-lock-and-runner-fingerprint-not-current-proof'-and[string]$dossier.historical_lineage.source_tree_correction_superseded_run.status-ceq'superseded-by-corrected-source-tree-lock-not-current-proof'-and(Test-A03HistoricalLineageBindings $dossier))'[mir4-a03-closure-lineage]'
if($RequireLocalEvidence){
  Assert-A03Closure((Get-A03ClosureSha256 $lockPath)-ceq[string]$proof.environment_lock.raw_sha256)'[mir4-a03-closure-lock-raw]'
  foreach($artifact in @($proof.configuration.source_mod_list,$proof.configuration.launch_mod_list,$proof.configuration.source_mod_settings,$proof.configuration.post_engine_mod_settings,$proof.execution.attempt.structured_result,$proof.execution.attempt.executor_stdout,$proof.execution.attempt.executor_stderr,$proof.execution.runtime.result_file,$proof.execution.runtime.stdout,$proof.execution.runtime.stderr,$proof.execution.runtime.factorio_log,$proof.execution.runtime.save)){Assert-A03Artifact $artifact}
  foreach($name in @('plan','summary','attempt')){$binding=$proof.execution.$name;$path=Resolve-A03ClosurePath([string]$binding.path)$true;Assert-A03Closure((Get-A03ClosureSha256 $path)-ceq[string]$binding.raw_sha256)"[mir4-a03-closure-execution-raw] $name"}
